-- Schema + seed para Shopify Dev Docs
-- Ejecuta este archivo en MySQL 8+

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS pages;
DROP TABLE IF EXISTS site_settings;

CREATE TABLE site_settings (
  setting_key VARCHAR(100) NOT NULL PRIMARY KEY,
  setting_value TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE pages (
  id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(120) NOT NULL UNIQUE,
  label VARCHAR(180) NOT NULL,
  file_name VARCHAR(180) NOT NULL UNIQUE,
  nav_order INT NOT NULL,
  hero_title TEXT NOT NULL,
  hero_subtitle TEXT NOT NULL,
  card1_title TEXT NOT NULL,
  card1_body TEXT NOT NULL,
  card2_title TEXT NOT NULL,
  card2_body TEXT NOT NULL,
  card3_title TEXT NOT NULL,
  card3_body TEXT NOT NULL,
  code_snippet MEDIUMTEXT NOT NULL DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO site_settings (setting_key, setting_value) VALUES
  ('site_title', 'Shopify Dev Docs'),
