  ('sidebar_foot', 'Documentacion visual y profesional del ecosistema Shopify: themes, Liquid, arquitectura y rendimiento.'),
  ('footer_left', 'Shopify Dev Docs'),
  ('footer_right_prefix', 'Contenido en MySQL'),
  ('playground_title', 'Simulador server-side'),
  ('playground_description', 'Procesa template y JSON en PHP, sin JavaScript.'),
  ('playground_template_label', 'Template'),
  ('playground_data_label', 'Datos JSON'),
  ('playground_button_label', 'Ejecutar simulacion'),
